**What this code covers**

- Toy CQRS implementation: separate write model (normalized) and read models (denormalized views), kept in sync by an in-memory event bus.
- Normalized order store: orders table + items table (conceptually).
- Denormalized: customer_id -> [order summaries].
- Denormalized: product -> total revenue.
- Events emitted by the write side
- Write side: normalized, transactional, validates commands
- Read model 1: orders_by_customer (fast customer-history lookup)
- Read model 2: revenue_by_product (analytics)

**Defines:** `OrderPlaced`, `OrderCancelled`, `OrderShipped`, `OrderWriteModel`, `OrdersByCustomerView`, `RevenueByProductView`, `OrderSearchView`, `EventBus`, `QueryAPI`

```python
"""
Toy CQRS implementation: separate write model (normalized) and read models
(denormalized views), kept in sync by an in-memory event bus.
"""
from dataclasses import dataclass
from typing import Dict, List, Callable

# --- Events emitted by the write side ---
@dataclass(frozen=True)
class OrderPlaced:      order_id: str; customer_id: str; product: str; amount: int
@dataclass(frozen=True)
class OrderCancelled:   order_id: str; reason: str
@dataclass(frozen=True)
class OrderShipped:     order_id: str; tracking: str

# --- Write side: normalized, transactional, validates commands ---
class OrderWriteModel:
    """Normalized order store: orders table + items table (conceptually)."""
    def __init__(self, bus):
        self.orders: Dict[str, dict] = {}     # order_id -> {customer, product, amount, status}
        self.bus = bus

    def place_order(self, order_id, customer_id, product, amount):
        if amount <= 0: raise ValueError("amount must be positive")
        if order_id in self.orders: raise ValueError("duplicate order")
        self.orders[order_id] = {
            "customer_id": customer_id, "product": product,
            "amount": amount, "status": "placed",
        }
        self.bus.publish(OrderPlaced(order_id, customer_id, product, amount))

    def cancel_order(self, order_id, reason):
        o = self.orders.get(order_id)
        if not o: raise ValueError("no such order")
        if o["status"] != "placed": raise ValueError(f"cannot cancel {o['status']}")
        o["status"] = "cancelled"
        self.bus.publish(OrderCancelled(order_id, reason))

    def ship_order(self, order_id, tracking):
        o = self.orders.get(order_id)
        if not o or o["status"] != "placed": raise ValueError("not shippable")
        o["status"] = "shipped"
        self.bus.publish(OrderShipped(order_id, tracking))

# --- Read model 1: orders_by_customer (fast customer-history lookup) ---
class OrdersByCustomerView:
    """Denormalized: customer_id -> [order summaries]. O(1) customer lookup."""
    def __init__(self): self.by_customer: Dict[str, list] = {}
    def handle(self, e):
        if isinstance(e, OrderPlaced):
            self.by_customer.setdefault(e.customer_id, []).append({
                "order_id": e.order_id, "product": e.product,
                "amount": e.amount, "status": "placed"})
        elif isinstance(e, OrderCancelled):
            self._set_status(e.order_id, "cancelled")
        elif isinstance(e, OrderShipped):
            self._set_status(e.order_id, "shipped")
    def _set_status(self, order_id, status):
        for orders in self.by_customer.values():
            for o in orders:
                if o["order_id"] == order_id: o["status"] = status
    def query(self, customer_id): return self.by_customer.get(customer_id, [])

# --- Read model 2: revenue_by_product (analytics) ---
class RevenueByProductView:
    """Denormalized: product -> total revenue. O(1) revenue query."""
    def __init__(self): self.revenue: Dict[str, int] = {}
    def handle(self, e):
        if isinstance(e, OrderPlaced):
            self.revenue[e.product] = self.revenue.get(e.product, 0) + e.amount
        elif isinstance(e, OrderCancelled):
            self.revenue[e.product] = self.revenue.get(e.product, 0) - e.amount
    def query(self): return dict(self.revenue)

# --- Read model 3: order_search (full-text-ish search) ---
class OrderSearchView:
    """Pretend Elasticsearch: keyword -> [order_ids]."""
    def __init__(self): self.index: Dict[str, list] = {}
    def handle(self, e):
        if isinstance(e, OrderPlaced):
            for kw in e.product.lower().split():
                self.index.setdefault(kw, []).append(e.order_id)
    def search(self, keyword): return self.index.get(keyword.lower(), [])

# --- Event Bus: routes events to all subscribed projections ---
class EventBus:
    def __init__(self): self.subs: List[Callable] = []
    def subscribe(self, fn): self.subs.append(fn)
    def publish(self, event):
        for fn in self.subs: fn(event)

# --- Query API: routes queries to the right read model ---
class QueryAPI:
    def __init__(self, by_customer, revenue, search):
        self.by_customer = by_customer
        self.revenue = revenue
        self.search = search
    def get_orders_for_customer(self, cust_id):
        return self.by_customer.query(cust_id)
    def get_revenue_by_product(self):
        return self.revenue.query()
    def search_orders(self, keyword):
        return self.search.search(keyword)

# --- Demo: wire up write side, 3 read models, query API ---
bus = EventBus()
write = OrderWriteModel(bus)
v1 = OrdersByCustomerView(); v2 = RevenueByProductView(); v3 = OrderSearchView()
bus.subscribe(v1.handle); bus.subscribe(v2.handle); bus.subscribe(v3.handle)
api = QueryAPI(v1, v2, v3)

# Write some orders
write.place_order("o1", "alice", "laptop pro", 1500)
write.place_order("o2", "alice", "wireless mouse", 50)
write.place_order("o3", "bob",   "laptop stand", 80)
write.cancel_order("o2", "changed mind")
write.ship_order("o3", "TRK123")

# Read from denormalized views
print("alice's orders:", api.get_orders_for_customer("alice"))
print("revenue by product:", api.get_revenue_by_product())
print("search 'laptop':", api.search_orders("laptop"))
```
